import { useId } from 'react'

import logo from './logo-data.json'

type Props = {
  /** "full" = the whole window-decal lockup; "banner" = just the HANDWORKS banner (for the nav). */
  variant?: 'full' | 'banner'
  className?: string
  title?: string
}

/**
 * The Handworks window-decal logo, drawn in `currentColor` so it follows the text colour of wherever it sits.
 * The letters are cut out of the banner (like the decal on the glass), so the background shows through.
 * Artwork is generated by scripts/build-logo.mjs.
 */
export function Logo({ variant = 'full', className, title = 'Handworks Coffee Studio' }: Props) {
  const mask = `hw-cut-${useId().replace(/:/g, '')}`
  const viewBox = variant === 'banner' ? '10 36 682 182' : logo.viewBox
  return (
    <svg className={className} viewBox={viewBox} role="img" aria-label={title} focusable="false">
      <defs>
        <mask id={mask} maskUnits="userSpaceOnUse">
          <rect x="0" y="0" width="700" height="330" fill="#fff" />
          <path transform={logo.tilt} d={logo.word} fill="#000" />
        </mask>
      </defs>
      <path d={logo.banner} fill="currentColor" mask={`url(#${mask})`} />
      {variant === 'full' ? (
        <>
          <path d={logo.est} fill="currentColor" />
          <path d={logo.subtitle} fill="currentColor" />
          <path
            d={logo.ornament}
            fill="none"
            stroke="currentColor"
            strokeWidth="2"
            strokeLinecap="round"
            strokeLinejoin="round"
          />
        </>
      ) : null}
    </svg>
  )
}
